-- Fresh marked disposable DB only. SQL Auth fixtures; no real user/provider calls.
begin;
create function pg_temp.lr_ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Learner intent assertion: %',label;end if;end $$;
create function pg_temp.lr_denied(command text,expected text default '42501') returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate=expected then return;end if;raise exception 'Unexpected learner SQLSTATE %',sqlstate;end;raise exception 'Expected learner refusal';end $$;
create function pg_temp.lr_claim(n integer,assurance text default 'aal2',offset_seconds integer default 0) returns void language plpgsql security definer set search_path='' as $$
declare s uuid:=('d2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;t bigint;
begin select floor(extract(epoch from c.updated_at))::bigint into t from auth.mfa_amr_claims c where c.session_id=s;
perform set_config('request.jwt.claims',jsonb_build_object('sub',('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'session_id',s,'role','authenticated','aal',assurance,'user_metadata',jsonb_build_object('role','owner'),'amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',t+offset_seconds)))::text,true);end $$;
create function pg_temp.lr_fault() returns trigger language plpgsql as $$begin raise exception 'Controlled learner event append failure';end $$;
do $$begin execute format('grant usage on schema %I to authenticated',pg_my_temp_schema()::regnamespace::text);end $$;
insert into auth.users(id,raw_user_meta_data) select ('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,jsonb_build_object('display_name','Learner fixture '||n,'role','owner') from generate_series(1,10)n;
insert into auth.mfa_factors(id,user_id,factor_type,status) select ('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'totp','verified' from generate_series(1,10)n;
insert into auth.sessions(id,user_id,factor_id,aal) select ('d2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'aal2' from generate_series(1,10)n;
insert into auth.mfa_amr_claims(id,session_id,authentication_method,updated_at) select ('d4000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'totp',date_trunc('second',clock_timestamp())-interval '120 seconds' from generate_series(1,10)n;
insert into pipstart_staff_private.members(user_id,active) select ('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,n<>7 from unnest(array[1,2,3,4,7])n;
insert into pipstart_staff_private.roles values('d1000000-0000-4000-8000-000000000001','owner'),('d1000000-0000-4000-8000-000000000002','administrator'),('d1000000-0000-4000-8000-000000000003','administrator'),('d1000000-0000-4000-8000-000000000004','author');
insert into pipstart_staff_private.delegations values('d1000000-0000-4000-8000-000000000003','people.manage_learners');
update public.pipstart_profiles set role='admin' where user_id='d1000000-0000-4000-8000-000000000008';
select pg_temp.lr_ok(not has_table_privilege('authenticated','pipstart_staff_private.learner_requests','SELECT'),'raw requests private');
select pg_temp.lr_ok(not has_function_privilege('service_role','public.pipstart_staff_learner_prepare(uuid,uuid,text,timestamptz,text,text)','EXECUTE'),'service key cannot prepare');
select pg_temp.lr_ok(not has_function_privilege('authenticated','pipstart_staff_private.learner_fresh(uuid)','EXECUTE'),'freshness helper private');
set local role authenticated;
select pg_temp.lr_claim(3);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('a',64))$q$);
reset role;
update pipstart_staff_private.control set enabled=true;
set local role authenticated;
select pg_temp.lr_claim(2);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('a',64))$q$);
select pg_temp.lr_claim(4);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('a',64))$q$);
select pg_temp.lr_claim(5);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000009','auth_resume',null,'access_change',repeat('a',64))$q$);
select pg_temp.lr_claim(3,'aal1');
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('a',64))$q$);
select pg_temp.lr_claim(3,'aal2',1);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('a',64))$q$);
select pg_temp.lr_claim(3);
do $$declare n integer;begin foreach n in array array[1,3,7,8,99] loop
 perform pg_temp.lr_denied(format('select public.pipstart_staff_learner_receipt(%L,%L,%L,null,%L,%L)','d9000000-0000-4000-8000-000000000001',('d1000000-0000-4000-8000-'||lpad(n::text,12,'0')),'auth_resume','access_change',repeat('a',64)));end loop;end $$;
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_suspend',clock_timestamp()+interval '366 days','access_change',repeat('a',64))$q$,'22023');
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_suspend','infinity','access_change',repeat('a',64))$q$,'22023');
select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('a',64));
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000002','d1000000-0000-4000-8000-000000000009','auth_resume',null,'access_change',repeat('b',64))$q$);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'security_response',repeat('a',64))$q$);
reset role;
delete from pipstart_staff_private.delegations where user_id='d1000000-0000-4000-8000-000000000003';
set local role authenticated;select pg_temp.lr_claim(3);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('a',64))$q$);
reset role;
insert into pipstart_staff_private.delegations values('d1000000-0000-4000-8000-000000000003','people.manage_learners');
insert into pipstart_staff_private.members(user_id) values('d1000000-0000-4000-8000-000000000005');
set local role authenticated;select pg_temp.lr_claim(3);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('a',64))$q$);
reset role;
delete from pipstart_staff_private.members where user_id='d1000000-0000-4000-8000-000000000005';
select pg_temp.lr_ok((select consumed_at is null from pipstart_staff_private.receipts where token_hash=sha256(convert_to(repeat('a',64),'UTF8'))),'denials preserve receipt');
set local role authenticated;select pg_temp.lr_claim(3);
select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('a',64));
select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change','');
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'security_response','')$q$,'22023');
select pg_temp.lr_ok((public.pipstart_staff_learner_request('d9000000-0000-4000-8000-000000000001')->>'status')='intent_recorded','minimized request read');
select pg_temp.lr_claim(2);select pg_temp.lr_denied($q$select public.pipstart_staff_learner_request('d9000000-0000-4000-8000-000000000001')$q$);
reset role;
insert into pipstart_staff_private.delegations values('d1000000-0000-4000-8000-000000000002','people.manage_learners');
set local role authenticated;select pg_temp.lr_claim(2);select pg_temp.lr_denied($q$select public.pipstart_staff_learner_request('d9000000-0000-4000-8000-000000000001')$q$);
select pg_temp.lr_claim(1);select pg_temp.lr_ok((public.pipstart_staff_learner_request('d9000000-0000-4000-8000-000000000001')->>'status')='intent_recorded','Owner can read reviewed request');
reset role;
select pg_temp.lr_ok((select count(*)=1 from pipstart_staff_private.learner_requests) and (select count(*)=1 from pipstart_staff_private.learner_request_events),'one request and atomic event after replay');
select pg_temp.lr_denied($q$update pipstart_staff_private.learner_requests set reason_code='security_response'$q$);
select pg_temp.lr_denied($q$delete from pipstart_staff_private.learner_request_events$q$);
update auth.mfa_amr_claims set updated_at=date_trunc('second',clock_timestamp())-interval '30 seconds' where session_id='d2000000-0000-4000-8000-000000000003';
set local role authenticated;select pg_temp.lr_claim(3);
select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000003','d1000000-0000-4000-8000-000000000009','auth_resume',null,'access_change',repeat('c',64));
reset role;
create trigger controlled_learner_event_fault before insert on pipstart_staff_private.learner_request_events for each row execute function pg_temp.lr_fault();
set local role authenticated;select pg_temp.lr_claim(3);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000003','d1000000-0000-4000-8000-000000000009','auth_resume',null,'access_change',repeat('c',64))$q$,'P0001');
reset role;
select pg_temp.lr_ok(not exists(select 1 from pipstart_staff_private.learner_requests where request_id='d9000000-0000-4000-8000-000000000003') and (select consumed_at is null from pipstart_staff_private.receipts where token_hash=sha256(convert_to(repeat('c',64),'UTF8'))),'audit failure rolls request and consumption back');
drop trigger controlled_learner_event_fault on pipstart_staff_private.learner_request_events;
set local role authenticated;select pg_temp.lr_claim(3);
select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000003','d1000000-0000-4000-8000-000000000009','auth_resume',null,'access_change',repeat('c',64));
reset role;
select pg_temp.lr_ok((select count(*)=2 from pipstart_staff_private.learner_requests) and (select count(*)=2 from pipstart_staff_private.learner_request_events),'known rollback permits original transaction resubmission');

-- A separate fresh proof does not bypass an unexpired intent on the same target.
update auth.mfa_amr_claims set updated_at=date_trunc('second',clock_timestamp())-interval '10 seconds' where session_id='d2000000-0000-4000-8000-000000000003';
set local role authenticated;select pg_temp.lr_claim(3);
select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000004','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('d',64));
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000004','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('d',64))$q$);
reset role;
select pg_temp.lr_ok((select consumed_at is null from pipstart_staff_private.receipts where token_hash=sha256(convert_to(repeat('d',64),'UTF8'))),'duplicate target refusal preserves proof');
-- Removed factors and soft-deleted targets remain denied independently of metadata.
update auth.mfa_factors set status='unverified' where user_id='d1000000-0000-4000-8000-000000000003';
set local role authenticated;select pg_temp.lr_claim(3);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000005','d1000000-0000-4000-8000-000000000010','auth_resume',null,'access_change',repeat('e',64))$q$);
reset role;
update auth.mfa_factors set status='verified' where user_id='d1000000-0000-4000-8000-000000000003';
update auth.users set deleted_at=clock_timestamp() where id='d1000000-0000-4000-8000-000000000010';
set local role authenticated;select pg_temp.lr_claim(1);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000005','d1000000-0000-4000-8000-000000000010','auth_resume',null,'access_change',repeat('e',64))$q$);
reset role;
update auth.users set deleted_at=null where id='d1000000-0000-4000-8000-000000000010';
-- A receipt cannot outlive the provider verification window.
set local role authenticated;select pg_temp.lr_claim(1);
select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000005','d1000000-0000-4000-8000-000000000010','auth_resume',null,'access_change',repeat('e',64));
reset role;
update auth.mfa_amr_claims set updated_at=clock_timestamp()-interval '6 minutes' where session_id='d2000000-0000-4000-8000-000000000001';
set local role authenticated;select pg_temp.lr_claim(1);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000005','d1000000-0000-4000-8000-000000000010','auth_resume',null,'access_change',repeat('e',64))$q$);
reset role;
select pg_temp.lr_ok((select consumed_at is null from pipstart_staff_private.receipts where token_hash=sha256(convert_to(repeat('e',64),'UTF8'))),'expired provider proof remains unconsumed');
-- Canonical expiry binding survives a SQL session timezone change.
update auth.mfa_amr_claims set updated_at=date_trunc('second',clock_timestamp())-interval '60 seconds' where session_id='d2000000-0000-4000-8000-000000000001';
create temp table learner_test_expiry(t timestamptz);insert into learner_test_expiry values(date_trunc('second',clock_timestamp())+interval '1 hour');
grant select on learner_test_expiry to authenticated;
set local time zone 'America/New_York';
set local role authenticated;select pg_temp.lr_claim(1);
select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000006','d1000000-0000-4000-8000-000000000006','auth_suspend',(select t from pg_temp.learner_test_expiry),'security_response',repeat('f',64));
set local time zone 'UTC';
select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000006','d1000000-0000-4000-8000-000000000006','auth_suspend',(select t from pg_temp.learner_test_expiry),'security_response',repeat('f',64));
select pg_temp.lr_ok((public.pipstart_staff_learner_request('d9000000-0000-4000-8000-000000000006')->>'operation')='auth_suspend','Owner suspension is a recorded intent only');
reset role;
rollback;
